import { escapeHtml as esc } from './message-format.js';
const opt = value => Array.isArray(value) ? value[0] : value;
const date = ns => Number(ns) > 0 ? new Date(Number(BigInt(ns) / 1000000n)).toLocaleString() : 'No tickets yet';
export function downloadJson(text, filename) {
  const url = URL.createObjectURL(new Blob([text], {type:'application/json'}));
  const a = document.createElement('a'); a.href=url; a.download=filename; a.click();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}

export async function projectPrivacy({el, api, token, project, active}) {
  el.innerHTML='<p role="status">Loading privacy settings…</p>';
  try {
    const state=opt(await api().customerPrivacy(token(),project.id)); if(!active())return;
    if(!state)throw new Error('Privacy settings unavailable');
    const p=state.policy;
    el.innerHTML=`<section class="card customer-section" id="cpPrivacySection"><div class="customer-section-heading"><div><span class="eyebrow">PRIVACY & RETENTION</span><h3>Keep what you need. Delete the rest.</h3></div><span class="pill">Automatic deletion on</span></div><p>Delete the entire request, including contact details, messages, internal notes and custom fields. Ticket links stop working when the deletion deadline arrives.</p><form id="cpPrivacyForm"><div class="row"><div><label for="cpCompletedDays">Days after resolution or closure</label><input type="number" id="cpCompletedDays" min="7" max="730" required value="${p.completedDays}"></div><div><label for="cpInactiveDays">Days without activity · open requests</label><input type="number" id="cpInactiveDays" min="7" max="730" required value="${p.inactiveDays}"></div></div><label for="cpNotice">Your company’s privacy notice</label><input type="url" id="cpNotice" placeholder="https://your-company.com/privacy" maxlength="500" value="${esc(p.noticeUrl)}"><p class="kv">Shown before customers submit. Explain your purpose, legal basis, contact for privacy requests and retention. These periods are product defaults, not legal deadlines.</p><div id="cpShorter" class="privacy-confirm hidden"><label class="checkline"><input type="checkbox" id="cpConfirmShorter"> Apply shorter periods to existing requests too.</label><p class="kv">This project currently holds ${state.tickets} request(s). Requests past the new deadline become unavailable after a 24-hour grace period, or the existing upgrade grace period if later.</p></div><div class="btnrow"><button class="primary" type="submit">Save privacy settings</button><span id="cpPrivacyStatus" role="status"></span></div></form><div class="privacy-health"><span><strong>${state.tickets}</strong> stored</span><span><strong>${state.held}</strong> on hold</span><span><strong>${state.due}</strong> awaiting removal</span></div><p class="kv">Next deletion: ${date(state.nextDeletion)}<br>Last background check: ${Number(state.lastSweep)>0?date(state.lastSweep):'Waiting for the first check'}${Number(p.graceUntil)>Date.now()*1e6?`<br>Existing records protected until ${date(p.graceUntil)}`:''}</p><details><summary>Backups & deletion journal</summary><p>Deletion removes data from the active Desk. Existing snapshots and downloaded copies are separate. Configure backup rotation in Hub → Backups, explicitly remove expired snapshots, and keep a current deletion journal outside the snapshot you might restore.</p><p class="kv">The journal keeps ticket IDs, creation/deletion dates and a reason code for 365 days. It contains no names, addresses or messages, but is still restricted operational data. Keep backup lifetimes shorter than this journal window.</p><button type="button" id="cpJournal">Download deletion journal (${state.journalEntries})</button><p><a href="./customer-support.html#privacy" target="_blank" rel="noopener">Privacy & restore procedure ↗</a></p><details><summary>Reapply deletions after a restore</summary><p>Keep the restored Desk offline while applying a journal exported after those deletions. Matching requests are permanently erased, including restored retention holds. Review the procedure before reopening access.</p><label for="cpJournalFile">Deletion journal · JSON from this Desk and project</label><input type="file" id="cpJournalFile" accept=".json,application/json"><label class="checkline"><input type="checkbox" id="cpRestoreConfirm"> I reviewed the journal and want to erase matching restored tickets.</label><button type="button" id="cpReplay">Reapply deletions</button></details><p id="cpJournalStatus" role="status"></p></details></section>`;
    const $=id=>el.querySelector('#'+id);
    function shorter(){const yes=Number($('cpCompletedDays').value)<Number(p.completedDays)||Number($('cpInactiveDays').value)<Number(p.inactiveDays);$('cpShorter').classList.toggle('hidden',!yes);$('cpConfirmShorter').required=yes;return yes;}
    $('cpCompletedDays').oninput=shorter; $('cpInactiveDays').oninput=shorter;
    $('cpPrivacyForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;if(shorter()&&!$('cpConfirmShorter').checked){$('cpPrivacyStatus').textContent='Confirm the shorter periods before saving.';return;}b.disabled=true;
      try{const r=await api().saveCustomerPrivacy(token(),project.id,p.revision,{completedDays:BigInt($('cpCompletedDays').value),inactiveDays:BigInt($('cpInactiveDays').value),noticeUrl:$('cpNotice').value.trim()},$('cpConfirmShorter').checked);if(!active())return;$('cpPrivacyStatus').textContent=r.detail;if(r.ok){p.revision+=1n;p.completedDays=BigInt($('cpCompletedDays').value);p.inactiveDays=BigInt($('cpInactiveDays').value);project.revision+=1n;shorter();await projectPrivacy({el,api,token,project,active});if(active())$('cpPrivacyStatus').textContent=r.detail;}}
      catch{if(active())$('cpPrivacyStatus').textContent='Could not confirm the change. Reload before retrying.';}finally{if(b.isConnected)b.disabled=false;}
    };
    $('cpJournal').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{let cursor=0n,revision=0n,journal,entries=[];do{const value=opt(await api().customerErasureJournal(token(),project.id,cursor,revision));if(!active())return;if(!value)throw new Error('Journal changed or access expired. Retry the download.');const page=JSON.parse(value);journal=page;entries.push(...page.entries);cursor=BigInt(page.next);revision=BigInt(page.revision);}while(cursor);journal.entries=entries;delete journal.next;downloadJson(JSON.stringify(journal,null,2),`desk-project-${project.id}-deletions.json`);$('cpJournalStatus').textContent='Journal downloaded. Store securely outside Desk backups.';}catch{if(active())$('cpJournalStatus').textContent='Could not download the journal.';}finally{b.disabled=false;}};
    $('cpReplay').onclick=async e=>{const b=e.currentTarget;if(!$('cpRestoreConfirm').checked){$('cpJournalStatus').textContent='Review and confirm the restore procedure first.';return;}b.disabled=true;
      try{const file=$('cpJournalFile').files[0];if(!file||file.size>12_000_000)throw new Error('Choose a journal JSON file up to 12 MB.');const journal=JSON.parse(await file.text());if(!active())return;
        if(journal.format!=='desk-erasure-journal-v1'||String(journal.projectId)!==String(project.id)||!Array.isArray(journal.entries)||journal.entries.length>60000)throw new Error('Choose a journal for this project.');
        const rows=journal.entries.map(r=>({ticketId:BigInt(r.ticketId),projectId:BigInt(r.projectId),createdAt:BigInt(r.createdAt),deletedAt:BigInt(r.deletedAt),reason:String(r.reason)}));
        for(let i=0;i<rows.length;i+=100){if(!active())return;const r=await api().replayCustomerErasures(token(),journal.canister,project.id,rows.slice(i,i+100));if(!active())return;if(!r.ok)throw new Error(r.detail);$('cpJournalStatus').textContent=`Processed ${Math.min(i+100,rows.length)} of ${rows.length} entries…`;}
        if(active()){$('cpJournalStatus').textContent='Journal applied. Complete the backup procedure before restoring access.';$('cpJournalFile').value='';$('cpRestoreConfirm').checked=false;}
      }catch(e){if(active())$('cpJournalStatus').textContent=(e.message||'Could not apply journal')+' Earlier successful batches remain applied; an unchanged journal can be retried.';}finally{b.disabled=false;}
    };
  }catch{if(active())el.innerHTML='<section class="card customer-section"><h3>Privacy settings unavailable</h3><p>Reload this project to retry. The existing retention policy continues running.</p></section>';}
}

export function ticketPrivacy({el,customer,ticket,api,token,admin,active,reload,onErase}) {
  const hold=opt(customer.hold),held=hold&&Number(hold.until)>Date.now()*1e6;
  el.innerHTML=`<details><summary>Data & privacy</summary><p>Scheduled deletion<br><strong>${date(customer.deleteAt)}</strong></p>${held?`<p class="privacy-confirm">Retention hold until ${date(hold.until)}<br>${esc(hold.reason)}</p>`:''}${admin?`<p class="kv">Verify the requester’s identity and scope before handling an access or erasure request. The contact email above is unverified.</p><button type="button" id="tpExport">Export for privacy review</button><p class="kv">The export includes internal notes. Review it for other people’s data before sharing. API keys and private-link secrets are excluded.</p><details><summary>${held?'Manage retention hold':'Keep temporarily for a documented reason'}</summary><label for="tpDays">Hold for days · maximum 365</label><input type="number" id="tpDays" min="1" max="365" value="30"><label for="tpReason">Justification · no sensitive details</label><input type="text" id="tpReason" maxlength="200" value="${esc(held?hold.reason:'')}" placeholder="e.g. Open contractual dispute"><button type="button" id="tpHold">Save temporary hold</button>${held?'<button type="button" id="tpRelease">Release hold</button><label class="checkline"><input type="checkbox" id="tpReleaseConfirm"> I reviewed the reason. Apply the normal deletion deadline now.</label>':''}</details><details><summary>Delete this customer request</summary><p>Permanently remove the contact, conversation, internal notes and fields from active Desk. The private link is revoked. Backups require the project’s deletion journal.</p><label for="tpConfirm">Type ${esc(ticket.key)} to confirm</label><input type="text" id="tpConfirm" autocomplete="off"><button type="button" class="danger" id="tpErase" ${held?'disabled':''}>Delete permanently</button></details><p id="tpStatus" role="status"></p>`:'<p class="kv">Hub-assigned Desk admins manage exports, erasure requests and temporary holds.</p>'}</details>`;
  if(!admin)return;
  const $=id=>el.querySelector('#'+id);
  async function action(button,work,done){button.disabled=true;try{const r=await work();if(!active())return;if(r?.ok===false)throw new Error(r.detail);$('tpStatus').textContent=r?.detail||'Done';await done?.(r);}catch(e){if(active())$('tpStatus').textContent=e.message||'Could not confirm the action. Please reload.';}finally{if(button.isConnected)button.disabled=false;}}
  $('tpExport').onclick=e=>action(e.currentTarget,()=>api().exportCustomerTicket(token(),ticket.id),r=>{const value=opt(r);if(!value)throw new Error('Ticket unavailable');downloadJson(value,`${ticket.key}-privacy-review.json`);});
  $('tpHold').onclick=e=>action(e.currentTarget,()=>api().holdCustomerTicket(token(),ticket.id,BigInt($('tpDays').value),$('tpReason').value),reload);
  if(held)$('tpRelease').onclick=e=>{if(!$('tpReleaseConfirm').checked){$('tpStatus').textContent='Review and confirm removal of the hold.';return;}action(e.currentTarget,()=>api().holdCustomerTicket(token(),ticket.id,0n,''),reload);};
  $('tpErase').onclick=e=>{if($('tpConfirm').value!==ticket.key){$('tpStatus').textContent='Type the ticket key exactly to confirm.';return;}action(e.currentTarget,()=>api().eraseCustomerTicket(token(),ticket.id,ticket.updatedAt,$('tpConfirm').value),onErase);};
}
